Notation UFLOW_DEPTH := 2368%Z (only parsing).    (* [comment removed for export] *)
Definition uflow_entry : Z := 0x1fb024.

(* [comment removed for export] *)
Definition ssp_cells (m : mem) (g : word) : Prop :=
  ro_cells asegs m 0x212628 [C8 (Z_to_bv 64 0x783758)] /\ ro_cells asegs m 0x783758 [C8 g].

(* [comment removed for export] *)
Definition uflow_res (j : nat) (kb : list byte) : word :=
  match j, kb with O, _ => SF_M1 | S _, b :: _ => Z_to_bv 64 (bv_unsigned b) | S _, [] => SF_M1 end.

