Notation SHGETC_DEPTH := 2400%Z (only parsing).    (* [comment removed for export] *)
Definition shgetc_entry : Z := 0x1ff914.

Definition shgetc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (f src : Z) (st : sfst) (j : nat) (kb : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (shcnt' : word) (m' : mem),
    let len' := Z.min (Z.of_nat j) 1 in
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (uflow_res j kb) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(f, f + 232); (bv_unsigned sp - SHGETC_DEPTH, bv_unsigned sp)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' f (sfile (mkSF (src + len') (src + Z.of_nat j) 0 0 0 (sf_read st) (sf_buf st) (sf_bsz st) SF_M1 (sf_lock st)
                                    (src + Z.of_nat j) (match j with O => src | S _ => src + Z.of_nat j end)
                                    (match j with O => SF_M1 | S _ => sf_shlim st end) shcnt'))
    /\ bytes_at asegs m' src kb
    /\ (j = 0%nat -> shcnt' = Z_to_bv 64 (sf_rpos st - src + bv_unsigned (sf_shcnt st))).   (* [comment removed for export] *)

Theorem shgetc_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (f src : Z) (st : sfst) (j : nat) (kb : list byte) (g : word) (lo : Z),
  a0 = Z_to_bv 64 f ->
  rw_cells asegs m f (sfile st) -> sf_ok st -> sf_wpos st = sf_wbase st -> (sf_mode st = Z_to_bv 64 0 \/ sf_mode st = SF_M1) ->
  sf_read st = string_read_entry -> sf_cookie st = src -> sf_buf st + sf_bsz st < 2^47 -> sf_shlim st = Z_to_bv 64 0 -> sf_buf st <= src ->
  bv_unsigned sp <= f -> f + 232 <= 2^47 ->
  bytes_at asegs m src kb -> find_byte 0 (firstn (Z.to_nat 257) kb) = Some j -> (j < 8)%nat -> memchr_ok src 0 257 kb -> 0 < src ->
  src + Z.of_nat (length kb) <= lo ->
  chk_ok m src (Z.of_nat j + 1) -> chk_ok m (bv_unsigned sp - 81) 1 -> m2s_cells m -> icells_mc m -> icells m -> ssp_cells m g ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - SHGETC_DEPTH -> kHighShadowEnd + 8 <= lo ->
  mem_inv asegs m ->
  evt asegs (shgetc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc f src st j kb lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
